// Verify X-Aegis-Signature = v1=HMAC-SHA256(secret, '<X-Aegis-Timestamp>.' + raw body) and reject timestamps older than
// 300 s. The secret is a read-only file mounted by tools/n8n/start_n8n.sh; it never appears in the workflow or its executions.
const crypto = require('crypto');
const fs = require('fs');
const secret = fs.readFileSync('/run/aegis/hmac.secret', 'utf8').trim();
const item = $input.first();
const h = item.json.headers || {};
const ts = String(h['x-aegis-timestamp'] || '');
const sig = String(h['x-aegis-signature'] || '');
let raw;
if (item.binary && item.binary.data) {
  raw = await this.helpers.getBinaryDataBuffer(0, 'data');
} else {
  raw = Buffer.from(JSON.stringify(item.json.body || {}));
}
const expected = 'v1=' + crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');
const age = Math.abs(Date.now() / 1000 - Number(ts));
const sigOk = sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
const fresh = /^[0-9]+$/.test(ts) && age <= 300;
let notice = null;
if (sigOk && fresh) {
  try { notice = JSON.parse(raw.toString('utf8')); } catch (e) { notice = null; }
}
const verified = Boolean(sigOk && fresh && notice);
return [{ json: { verified, reason: verified ? 'ok' : (!fresh ? 'stale or missing timestamp' : 'bad signature'), notice: verified ? notice : null, received_at: new Date().toISOString() } }];

// HIGH: incomplete run, anomaly detector fired, or an answer withheld (canary / secret / unscanned). Page-worthy.
const fs = require('fs');
const n = $input.first().json;
const line = JSON.stringify({ route: 'high', received_at: n.received_at, notice: n.notice }) + '\n';
fs.appendFileSync('/incidents/incidents.jsonl', line);
fs.appendFileSync('/incidents/HIGH.jsonl', line);
return [{ json: { ok: true, route: 'high', run_id: n.notice.run_id } }];

// MEDIUM: the model produced unsafe output that the defence let through (a finding for the blue team).
const fs = require('fs');
const n = $input.first().json;
fs.appendFileSync('/incidents/incidents.jsonl', JSON.stringify({ route: 'medium', received_at: n.received_at, notice: n.notice }) + '\n');
return [{ json: { ok: true, route: 'medium', run_id: n.notice.run_id } }];

// LOW: sealed and complete, nothing withheld, no detector fired.
const fs = require('fs');
const n = $input.first().json;
fs.appendFileSync('/incidents/incidents.jsonl', JSON.stringify({ route: 'low', received_at: n.received_at, notice: n.notice }) + '\n');
return [{ json: { ok: true, route: 'low', run_id: n.notice.run_id } }];
